package ir.hashemi.smsforwarder;
import android.app.*;import android.content.*;import android.os.Build;
public class NotificationHelper{static final String CH="sms_forwarder_status";static final int ID=7;static void show(Context c,String text){NotificationManager n=(NotificationManager)c.getSystemService(Context.NOTIFICATION_SERVICE);if(Build.VERSION.SDK_INT>=26)n.createNotificationChannel(new NotificationChannel(CH,"SMS Forwarder",NotificationManager.IMPORTANCE_LOW));PendingIntent p=PendingIntent.getActivity(c,0,new Intent(c,MainActivity.class),PendingIntent.FLAG_IMMUTABLE|PendingIntent.FLAG_UPDATE_CURRENT);Notification.Builder b=Build.VERSION.SDK_INT>=26?new Notification.Builder(c,CH):new Notification.Builder(c);b.setSmallIcon(android.R.drawable.stat_notify_more).setContentTitle("SMS Forwarder").setContentText(text).setOngoing(true).setContentIntent(p);n.notify(ID,b.build());}static void hide(Context c){((NotificationManager)c.getSystemService(Context.NOTIFICATION_SERVICE)).cancel(ID);}}
